INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(49611, 'Jeremiah 46:21', 'Jeremiah', 46, 21, 'د مِصر د کرايه فوجيان لکه د کمزورو سخو په شان دى. هغوئ به هم په يو ځائ راوګرځى او په شريکه به وتښتى، هغوئ به په خپل ځائ باندې ونۀ دريږى. ځکه چې په هغوئ د تباهۍ او افت ورځ راروانه ده، دا د هغوئ دپاره د سزا ورکولو ورځ ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_21.mp3', '', 1761754199, 1761754199),
(49612, 'Jeremiah 46:22', 'Jeremiah', 46, 22, 'مِصر به لکه د مار په شان کشار وکړى او په وروستو به وتښتى کله چې د دشمن فوج ورباندې حمله وکړى، هغوئ به د دوئ خلاف تبر په لاس راشى او په دوئ به داسې حمله وکړى لکه څنګه چې يو سړے ونې وهى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_22.mp3', '', 1761754199, 1761754199),
(49613, 'Jeremiah 46:23', 'Jeremiah', 46, 23, 'مالِک خُدائ فرمائى چې، هغوئ به د مِصر خلق د ځنګلى ونو په شان ووهى، ځکه چې د هغوئ شمېر د مُولخانو نه هم ډېر بې‌شمېره دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_23.mp3', '', 1761754199, 1761754199),
(49614, 'Jeremiah 46:24', 'Jeremiah', 46, 24, 'د مِصر خلق به وشرميږى، او د شمال خلقو ته به حواله کړے شى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_24.mp3', '', 1761754199, 1761754199),
(49615, 'Jeremiah 46:25', 'Jeremiah', 46, 25, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، ”زۀ به امون د مِصر د تيبس معبود او د مِصر نورو معبودانو ته سزا ورکړم. زۀ به د مِصر بادشاهانو او فِرعون ته او هغوئ ټولو ته سزا ورکړم څوک چې په هغۀ يقين کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_25.mp3', '', 1761754199, 1761754199),
(49616, 'Jeremiah 46:26', 'Jeremiah', 46, 26, 'مالِک خُدائ فرمائى چې، زۀ به هغوئ هغه خلقو ته حواله کړم څوک چې دوئ وژل غواړى، نبوکدنضر د بابل بادشاه او د هغۀ آفسرانو ته. خو وروستو به مِصر کښې د وړاندې په شان خلق بيا آباد شى. دا مالِک خُدائ فرمائى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_26.mp3', '', 1761754199, 1761754199),
(49617, 'Jeremiah 46:27', 'Jeremiah', 46, 27, '”اے زما خِدمتګاره يعقوبه مۀ يرېږه، اے اِسرائيله مۀ يرېږه. زۀ به تاسو د هغه لرې مُلک نه دوباره خپلو کورونو ته راولم، چرته چې تاسو جلاوطن شوى يئ. ستا اولاد به زۀ خپلو کورونو ته د جلاوطنۍ نه واپس راولم. يعقوب به دوباره خپل مُلک ته راشى او په امن او سکون سره به ژوند کوى، او تاسو به څوک هم نۀ يروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_27.mp3', '', 1761754199, 1761754199),
(49618, 'Jeremiah 46:28', 'Jeremiah', 46, 28, 'مالِک خُدائ فرمائى چې، اے زما خِدمتګاره يعقوبه مۀ يرېږه، ځکه زۀ تا سره يم. زۀ به په پوره توګه هغه قومونه تباه کړم کومو ته چې تاسو ما جلا وطن کړى وئ، خو زۀ به تاسو په مکمل توګه نۀ تباه کوم. زۀ به ستاسو په اِنصاف سره تنبيه وکړم، زۀ به تاسو بې‌سزا نۀ پرېږدم.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah46_verse_28.mp3', '', 1761754199, 1761754199),
(49619, 'Proverbs 10:1', 'Proverbs', 10, 1, 'دا د سلیمان متلونه دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_1.mp3', '', 1761754199, 1761754199),
(49620, 'Proverbs 10:2', 'Proverbs', 10, 2, 'هغه دولت چې د ناروا لارې تر‌لاسه کیږي ګټه نه لري خو صداقت انسان له مرګ نه ژغوري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_2.mp3', '', 1761754199, 1761754199),
(49621, 'Proverbs 10:3', 'Proverbs', 10, 3, 'څښتن نېک انسان لوږې ته نه پرېږدي خو د بدکارانو غوښتنې شنډوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_3.mp3', '', 1761754199, 1761754199),
(49622, 'Proverbs 10:4', 'Proverbs', 10, 4, 'بېکاره لاسونه انسان خواروي خو زحمت کښه لاسونه انسان شتمن کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_4.mp3', '', 1761754199, 1761754199),
(49623, 'Proverbs 10:5', 'Proverbs', 10, 5, 'هوښیار زوی په اوړي کې خپل فصل راټولوي خو د لو په وخت کې ویده شوی زوی شرم راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_5.mp3', '', 1761754199, 1761754199),
(49624, 'Proverbs 10:6', 'Proverbs', 10, 6, 'برکت د نېک سړي د سر تاج دی خو د بدکارانو ظلم د هغوی په خوله پرده اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_6.mp3', '', 1761754199, 1761754199),
(49625, 'Proverbs 10:7', 'Proverbs', 10, 7, 'د نېک سړي یادول د برکت سبب کیږي خو د بدکارانو د نوم نه زړه بدیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_7.mp3', '', 1761754199, 1761754199),
(49626, 'Proverbs 10:8', 'Proverbs', 10, 8, 'د حکمت خاوند حکمونه مني خو د جاهل انسان خپله ژبه بلا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_8.mp3', '', 1761754199, 1761754199),
(49627, 'Proverbs 10:9', 'Proverbs', 10, 9, 'څوک چې خپل ژوند په صداقت تېروي ډاډه ګرځي خو د کږو لارو خاوند به رسوا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_9.mp3', '', 1761754199, 1761754199),
(49628, 'Proverbs 10:10', 'Proverbs', 10, 10, 'څوک چې سترګې وهي دردونه جوړوي او د جاهل انسان خپله ژبه بلا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_10.mp3', '', 1761754199, 1761754199),
(49629, 'Proverbs 10:11', 'Proverbs', 10, 11, 'د نېک انسان خوله د ژوند سرچینه ده خو د بدکارانو خوله په ظلم پرده اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_11.mp3', '', 1761754199, 1761754199),
(49630, 'Proverbs 10:12', 'Proverbs', 10, 12, 'کرکه جګړو ته لمن وهي خو مینه په ټولو ګناهونو پرده اچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_12.mp3', '', 1761754199, 1761754199),
(49631, 'Proverbs 10:13', 'Proverbs', 10, 13, 'حکمت د عقلمن په خبرو کې موندل کیږي خو د ناپوه د ملا دپاره لښته ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_13.mp3', '', 1761754199, 1761754199),
(49632, 'Proverbs 10:14', 'Proverbs', 10, 14, 'د حکمت خاوندان خپل علم ذخیره کوي خو د جاهلانو د خولې خبرې بربادي راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_14.mp3', '', 1761754199, 1761754199),
(49633, 'Proverbs 10:15', 'Proverbs', 10, 15, 'د شتمن مال دولت د هغه دپاره کلا ده خو غریبي د غریبانو دپاره بلا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_15.mp3', '', 1761754199, 1761754199),
(49634, 'Proverbs 10:16', 'Proverbs', 10, 16, 'د نېک انسان انعام ژوندون دی خو د بدکاره انسان ګټه ګناه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_16.mp3', '', 1761754199, 1761754199),
(49635, 'Proverbs 10:17', 'Proverbs', 10, 17, 'نصیحت منونکی نور خلک د ژوندون په لاره روانوي خو اصلاح نه منونکی نور خلک بې‌لارې کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_17.mp3', '', 1761754199, 1761754199),
(49636, 'Proverbs 10:18', 'Proverbs', 10, 18, 'څوک چې په دروغو خپله کرکه پټوي او په نورو تور لګوي، هغه کم‌عقل دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_18.mp3', '', 1761754199, 1761754199),
(49637, 'Proverbs 10:19', 'Proverbs', 10, 19, 'ډېرې خبرې کول د ګناه سبب ګرځي خو څوک چې ژبه په خپل واک کې ساتي هوښیار دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_19.mp3', '', 1761754199, 1761754199),
(49638, 'Proverbs 10:20', 'Proverbs', 10, 20, 'د نېک سړي د خولې خبرې سوچه سپین زر دي خو د بدکارانو د زړه خیالونه ارزښت نه لري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_20.mp3', '', 1761754199, 1761754199),
(49639, 'Proverbs 10:21', 'Proverbs', 10, 21, 'د نېک سړي د خولې خبرې خلک مړوي خو د جاهلانو ناپوهي هغوی مړه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_21.mp3', '', 1761754199, 1761754199),
(49640, 'Proverbs 10:22', 'Proverbs', 10, 22, 'د څښتن برکت انسان شتمن کوي خو زحمتونه هېڅ شی نه شي زیاتولی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_22.mp3', '', 1761754199, 1761754199),
(49641, 'Proverbs 10:23', 'Proverbs', 10, 23, 'کم‌عقل د خپل بد عمل نه خوند اخلي خو د پوهې خاوند له حکمت نه خوند اخلي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_23.mp3', '', 1761754199, 1761754199),
(49642, 'Proverbs 10:24', 'Proverbs', 10, 24, 'له هغې بلا نه چې بدکاره وېریږي هغه پرې نازلیږي خو نېکان چې څه شی غواړي هغه ورته ورکول کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_24.mp3', '', 1761754199, 1761754199),
(49643, 'Proverbs 10:25', 'Proverbs', 10, 25, 'کله چې سخت توفان راشي نو بدکاره انسان به تباه شي خو د نېک انسان بنیاد به تل ټینګ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_25.mp3', '', 1761754199, 1761754199),
(49644, 'Proverbs 10:26', 'Proverbs', 10, 26, 'لټ انسان د کار ورکوونکو دپاره داسې دی لکه سرکه چې غاښونه برېښوي او لوګی سترګې سوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_26.mp3', '', 1761754199, 1761754199),
(49645, 'Proverbs 10:27', 'Proverbs', 10, 27, 'له څښتن څخه وېره عمر اوږدوي خو د بدکارانو عمر به لنډ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_27.mp3', '', 1761754199, 1761754199),
(49646, 'Proverbs 10:28', 'Proverbs', 10, 28, 'د نېکانو ارمانونه چې پوره کیږي نو خوشحالیږي خو د بدکارانو امیدونه تباه کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_28.mp3', '', 1761754199, 1761754199),
(49647, 'Proverbs 10:29', 'Proverbs', 10, 29, 'د څښتن لار د پاک زړه د خاوند دپاره کلا ده خو د شر اچوونکو دپاره بلا ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_29.mp3', '', 1761754199, 1761754199),
(49648, 'Proverbs 10:30', 'Proverbs', 10, 30, 'د نېک انسان بنیاد به هېڅکله ونه لړزیږي خو بدکاران به د ځمکې په سر پاتې نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_30.mp3', '', 1761754199, 1761754199),
(49649, 'Proverbs 10:31', 'Proverbs', 10, 31, 'د نېک انسان خوله د حکمت خبرې کوي خو کږه ژبه به پرې کړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_31.mp3', '', 1761754199, 1761754199),
(49650, 'Proverbs 10:32', 'Proverbs', 10, 32, 'د نېک انسان د خولې خبرې خوږې وي خو د بدکارانو د خولې خبرې کږې وږې وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/proverbs10_verse_32.mp3', '', 1761754199, 1761754199),
(49651, 'Psalms 24:1', 'Psalms', 24, 1, 'چې په ځمکه کې هرڅه دي هغه واړه د څښتن دي چې په دنیا کې اوسي هغه واړه د څښتن دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_1.mp3', '', 1761754199, 1761754199),
(49652, 'Psalms 24:2', 'Psalms', 24, 2, 'ځکه تهداب د ځمکې کېښود څښتن هغه یې کلکه ودروله دریابونو باندې هم یې قایمه ودروله په اوبو د ځمکې لاندې باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_2.mp3', '', 1761754199, 1761754199),
(49653, 'Psalms 24:3', 'Psalms', 24, 3, 'څوک شي ختلی د څښتن غونډۍ ته؟ څوک ودرېدی شي د هغه پاک کور کې؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_3.mp3', '', 1761754199, 1761754199),
(49654, 'Psalms 24:4', 'Psalms', 24, 4, 'هغه څوک چې لاسونه یې په ګناه نه وي ککړ او زړه یې پاک وي چې د بتانو عبادت نه کوي او په دروغو قسمونه نه خوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_4.mp3', '', 1761754199, 1761754199),
(49655, 'Psalms 24:5', 'Psalms', 24, 5, 'نو برکت به د څښتن نه واخلي کړي د هغه ژغورونکی خدای به یې معصوم اعلان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_5.mp3', '', 1761754199, 1761754199),
(49656, 'Psalms 24:6', 'Psalms', 24, 6, 'دا هغه خلک دي چې کړي رجوع خدای ته څوک چې غواړي د یعقوب د خدای دیدار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_6.mp3', '', 1761754199, 1761754199),
(49657, 'Psalms 24:7', 'Psalms', 24, 7, 'ای دروازو خلاصې شئ شئ تاریخي دروازو تاسې بېرته چې د جلال پاچا راننوځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_7.mp3', '', 1761754199, 1761754199),
(49658, 'Psalms 24:8', 'Psalms', 24, 8, 'څوک دی دا د جلال پاچا؟ هغه څښتن چې دی قوي او زورور هغه څښتن چې دی تکړه په جنګ کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_8.mp3', '', 1761754199, 1761754199),
(49659, 'Psalms 24:9', 'Psalms', 24, 9, 'ای دروازو خلاصې شئ شئ بېرته تاسې تاریخي دروازو چې د جلال پاچا راننوځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_9.mp3', '', 1761754199, 1761754199),
(49660, 'Psalms 24:10', 'Psalms', 24, 10, 'څوک دی دا د جلال پاچا؟ دا مطلق قادر څښتن دی دا دی پاچا د جلال', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms24_verse_10.mp3', '', 1761754199, 1761754199),
(49661, 'Psalms 13:1', 'Psalms', 13, 1, 'ته ترڅو به هېروې ما ای څښتنه؟ تر ابده؟ ته ترڅو به اړوې خپل مخ زما نه؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms13_verse_1.mp3', '', 1761754199, 1761754199),
(49662, 'Psalms 13:2', 'Psalms', 13, 2, 'ترڅو به روح وي پرېشانۍ کې زما؟ ترڅو به هره ورځ زړګی له غمه ډک وي زما؟ ترڅو دښمن به بریالی وي په ما؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms13_verse_2.mp3', '', 1761754199, 1761754199),
(49663, 'Psalms 13:3', 'Psalms', 13, 3, 'راته وګوره څښتنه، زما خدایه ځواب راکړه ماته بیا خپل قوت راکړه هسې نه چې زه ویده د مرګ په خوب شم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms13_verse_3.mp3', '', 1761754199, 1761754199),
(49664, 'Psalms 13:4', 'Psalms', 13, 4, 'دښمن به وایي: «زه په ده شوم غالب» دوی به خوشحالي کړي چې مې ماتې وخوړله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms13_verse_4.mp3', '', 1761754199, 1761754199),
(49665, 'Psalms 13:5', 'Psalms', 13, 5, 'خو کړم باور ستا په تلپاتې مینه زړګی زما ستا په نجات کې خوشحالي کوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms13_verse_5.mp3', '', 1761754199, 1761754199),
(49666, 'Psalms 13:6', 'Psalms', 13, 6, 'زه به ستا د ثنا وایمه سندرې ای څښتنه ځکه چې ما سره دې کړی احسان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms13_verse_6.mp3', '', 1761754199, 1761754199),
(49667, 'Jeremiah 7:1', 'Jeremiah', 7, 1, '‏ مالِک خُدائ يرمياه له پېغام ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_1.mp3', '', 1761754199, 1761754199),
(49668, 'Jeremiah 7:2', 'Jeremiah', 7, 2, '”د مالِک خُدائ د کور د دروازې سره ودرېږه او خلقو ته اعلان وکړه چې، اے د يهوداه ټولو اوسېدونکو او هغه کسانو چې په دې لارو د مالِک خُدائ کور ته د عبادت دپاره دننه کيږى، د مالِک خُدائ کلام واورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_2.mp3', '', 1761754199, 1761754199),
(49669, 'Jeremiah 7:3', 'Jeremiah', 7, 3, 'مالِک خُدائ ربُ الافواج چې د بنى اِسرائيلو خُدائ پاک دے فرمائى چې د خپل چال چلن او سلوک اصلاح وکړئ، نو بيا به زۀ تاسو ته په دې زمکه د اوسېدو دپاره موقع درکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_3.mp3', '', 1761754199, 1761754199),
(49670, 'Jeremiah 7:4', 'Jeremiah', 7, 4, 'د هغوئ په دروغژنو خبرو مۀ دوکه کېږئ چې وائى، ”مونږ دلته په امن کښې يُو ځکه چې دا د خُدائ پاک کور، د خُدائ پاک کور، د خُدائ پاک کور دے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_4.mp3', '', 1761754199, 1761754199),
(49671, 'Jeremiah 7:5', 'Jeremiah', 7, 5, 'کۀ چرې په رښتيا سره تاسو خپل چال چلن او د ژوند طريقې بدلې کړئ، او په اِنصاف سره د يو بل سره معامله وکړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_5.mp3', '', 1761754199, 1761754199),
(49672, 'Jeremiah 7:6', 'Jeremiah', 7, 6, 'او چې نه تاسو په مسافر، يتيم او کونډه باندې ظلم وکړئ، او په دې ځائ کښې د بې‌ګناه وينه تويه نۀ کړئ، او د پردو معبودانو عبادت نه لاس په سر شئ او په دې خپل ځان ته نقصان مۀ رسوئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_6.mp3', '', 1761754199, 1761754199),
(49673, 'Jeremiah 7:7', 'Jeremiah', 7, 7, 'نو بيا به زۀ تاسو په هم دې مُلک کښې د اوسېدو دپاره پرېږدم کوم چې ما ستاسو پلار نيکۀ له د تل دپاره په ميراث کښې ورکړے وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_7.mp3', '', 1761754199, 1761754199),
(49674, 'Jeremiah 7:8', 'Jeremiah', 7, 8, 'خو ګورئ تاسو په دروغژنو خبرو باندې يقين ساتئ کومې چې بې‌فائدې دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_8.mp3', '', 1761754199, 1761754199),
(49675, 'Jeremiah 7:9', 'Jeremiah', 7, 9, 'تاسو غلا، قتل او زنا کوئ او د دروغو قسمونه خورئ، او د بعل بُت ته د خوشبويۍ نذرانې پېش کوئ، او د هغه غېرو معبودانو عبادت کوئ چې تاسو د مخکښې نه نۀ دى پېژندلى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_9.mp3', '', 1761754199, 1761754199),
(49676, 'Jeremiah 7:10', 'Jeremiah', 7, 10, 'او د دې نه وروستو هغه کور ته هم راځئ کوم چې زما په نامه ياديږى او زما په حضور کښې ودرېږئ او وايئ چې، ”مونږ په حفاظت کښې يُو،“ خو دوباره بيا خپلو ټولو حرامو کارونو پسې ګرځئ څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_10.mp3', '', 1761754199, 1761754199),
(49677, 'Jeremiah 7:11', 'Jeremiah', 7, 11, 'مالِک خُدائ فرمائى چې، ولې په کوم کور چې زما نامه ليکلے شوې ده د دې نه د ډاکوانو د پټېدو ځائ جوړ شوے دے څۀ؟ خبردار. څۀ چې تاسو کوئ زۀ دا هر څۀ ګورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_11.mp3', '', 1761754199, 1761754199),
(49678, 'Jeremiah 7:12', 'Jeremiah', 7, 12, 'تاسو د سيلا ښار ته لاړ شئ، په کوم ځائ کښې چې ما خپله وړومبۍ عبادتخانه جوړه کړې وه، نو هلته به درته دا پته ولګى چې ما خپل قوم بنى اِسرائيل سره د دوئ د شرارت په وجه هغه ښار سره څۀ کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_12.mp3', '', 1761754199, 1761754199),
(49679, 'Jeremiah 7:13', 'Jeremiah', 7, 13, 'مالِک خُدائ فرمائى چې، هرکله چې تاسو دا د شرارت کارونه کول، ما تاسو ته بار بار د دوئ په حقله وينا وکړه، خو تاسو زما وينا ته غوږ ونۀ نيولو. ما تاسو ته آواز درکړو خو تاسو جواب رانۀ کړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_13.mp3', '', 1761754199, 1761754199),
(49680, 'Jeremiah 7:14', 'Jeremiah', 7, 14, 'نو بيا چې ما کوم افت په سيلا ښار نازل کړے دے نو زۀ به هم هغه افت په دې عبادتخانې چې زما نوم پرې ليکلے شوے دے، او په دې عبادتخانه چې تاسو پرې يقين کوئ، او په دې ځائ چې ما ستاسو پلار نيکۀ او تاسو له درکړے دے نازل کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_14.mp3', '', 1761754199, 1761754199),
(49681, 'Jeremiah 7:15', 'Jeremiah', 7, 15, 'زۀ به تاسو د خپل حضور نه داسې وشړم لکه څنګه چې ما ستاسو خپلوان د اِفرائيم خلق شړلى وُو.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_15.mp3', '', 1761754199, 1761754199),
(49682, 'Jeremiah 7:16', 'Jeremiah', 7, 16, 'مالِک خُدائ وفرمائيل، ”اے يرمياه، دې قوم ته نوره دُعا مۀ کوه. او د هغوئ دپاره ما ته سوال او فرياد مۀ کوه، ما ته د هغوئ سره د مدد کولو سفارش مۀ کوه، ځکه چې زۀ به ستا خبره نۀ اورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_16.mp3', '', 1761754199, 1761754199),
(49683, 'Jeremiah 7:17', 'Jeremiah', 7, 17, 'ولې تۀ هغه څۀ نۀ وينې چې کوم هغوئ د يهوداه په ښارونو کښې او د يروشلم په کوڅو کښې کوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_17.mp3', '', 1761754199, 1761754199),
(49684, 'Jeremiah 7:18', 'Jeremiah', 7, 18, 'ماشومان خشاک راغونډوى، پلاران اور بلوى او ښځې اوړۀ اغږى او ترې نه پېړې جوړوى چې د آسمانې مَلِکې په نامه بُت ته ترې نازکې روټۍ پخې کړى. او هغوئ نورو معبودانو ته د څښلو نذرانې وړاندې کوى، او په خپل دې عمل ما غصه کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_18.mp3', '', 1761754199, 1761754199),
(49685, 'Jeremiah 7:19', 'Jeremiah', 7, 19, 'آيا هغوئ په خپل دې عمل سره ما ته نقصان رسوى څۀ؟ خو هغوئ خپل ځان ته نقصان رسوى او په خپل دې عمل سره خپل ځانونه شرموى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_19.mp3', '', 1761754199, 1761754199),
(49686, 'Jeremiah 7:20', 'Jeremiah', 7, 20, 'نو په دې وجه قادر مطلق خُدائ فرمائى، زما د قهر او غصې اور به د دې ځائ په انسانانو، ځناورو، او د مېدان په ونو او د زمکې په فصلونو نازل کړم. او هر څۀ به وسوزى او څوک به هم دا اور نۀ شى مړ کولے.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_20.mp3', '', 1761754199, 1761754199),
(49687, 'Jeremiah 7:21', 'Jeremiah', 7, 21, 'ربُ الافواج مالِک خُدائ د بنى اِسرائيلو خُدائ پاک داسې فرمائى، ”خپلې سوزېدونکې نذرانې او نورې قربانۍ واخلئ او په خپله يې غوښې وخورئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_21.mp3', '', 1761754199, 1761754199),
(49688, 'Jeremiah 7:22', 'Jeremiah', 7, 22, 'ځکه کله چې ما ستاسو پلار نيکۀ د مِصر نه بهر راوويستل او هغوئ سره مې خبرې وکړې او خپل حُکمونه مې دوئ له ورکړل، نو ما هغوئ له د سوزېدونکو نذرانو او د قربانۍ په حقله حُکم نۀ وو ورکړے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_22.mp3', '', 1761754199, 1761754199),
(49689, 'Jeremiah 7:23', 'Jeremiah', 7, 23, 'خو ما هغوئ له دا حُکم ورکړو، چې زما تابعدارى کوئ، نو زۀ به ستاسو خُدائ پاک يم او تاسو به زما خلق يئ. او د کومو لارو چې زۀ درته د تلو حکم کوم په هغې تلل کوئ. نو په دې کښې به ستا خير وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_23.mp3', '', 1761754199, 1761754199),
(49690, 'Jeremiah 7:24', 'Jeremiah', 7, 24, 'خو هغوئ زما دا حکم ونۀ منلو او زما کلام ته يې غوږ ونۀ نيولو، بلکې د خپل سرکشه زړۀ خواهشونه يې ومنل نو په دې باندې هغوئ د ښۀ کېدو په ځائ نور هم خراب شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_24.mp3', '', 1761754199, 1761754199),
(49691, 'Jeremiah 7:25', 'Jeremiah', 7, 25, 'د کومې ورځې نه چې ستاسو پلار نيکۀ د مِصر نه بهر راووتل تر اوسه پورې، ورځ په ورځ، وخت په وخت، ما خپل خِدمت کوونکى پېغمبران تاسو له درولېږل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_25.mp3', '', 1761754199, 1761754199),
(49692, 'Jeremiah 7:26', 'Jeremiah', 7, 26, 'خو هغوئ زما خبرو ته غوږ ونۀ نيولو او نۀ يې توجو ورکړه. او هغوئ سرکشه وُو تر دې چې د خپل پلار نيکۀ نه يې هم زيات بدکارونه وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_26.mp3', '', 1761754199, 1761754199),
(49693, 'Jeremiah 7:27', 'Jeremiah', 7, 27, 'نو اے يرمياه، کله چې تۀ دوئ ته دا هر څۀ ووائې دوئ به تا ته غوږ ونۀ نيسى، او کله چې تۀ دوئ ته آواز ورکړې دوئ به تا له جواب نۀ درکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_27.mp3', '', 1761754199, 1761754199),
(49694, 'Jeremiah 7:28', 'Jeremiah', 7, 28, 'نو دوئ ته ووايه، دا هغه قوم دے چې د مالِک خُدائ تابعدارى يې ونۀ کړله او اصلاح يې قبوله نۀ کړله. رښتينوالے د دوئ نه تلے دے، او هغه نور د دوئ د خُلو نه نۀ اورېدلے کيږى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_28.mp3', '', 1761754199, 1761754199),
(49695, 'Jeremiah 7:29', 'Jeremiah', 7, 29, '”خپل وېښتۀ د وير دپاره کل کړئ او لرې يې وغورزوئ. په اوچتو خُشکو غرونو د وير او ماتم سندرې ووايئ، ځکه چې مالِک خُدائ هغوئ رد کړل او دا نسل يې خپل قهر او غضب ته پرېښودلو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_29.mp3', '', 1761754199, 1761754199),
(49696, 'Jeremiah 7:30', 'Jeremiah', 7, 30, 'مالِک خُدائ فرمائى چې د يهوداه خلقو زما د سترګو د وړاندې ګنده کارونه کړى دى، هغوئ زما په کور کښې خپل پليت بُتان اېښى دى په کومو چې زما نوم ليکلے دے او هغه يې ناپاکه کړے دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_30.mp3', '', 1761754199, 1761754199),
(49697, 'Jeremiah 7:31', 'Jeremiah', 7, 31, 'او ورسره ورسره هغوئ د بنى‌هنوم په وادۍ کښې د توفت په نوم علاقائى عبادتخانې جوړې کړې چې هلته خپل زامن او لوڼه په اور کښې وسوزوى او قربانى يې کړى چې نۀ ورته ما حکم کړے وو او نۀ مې په خيال خاطر کښې تېر شوى وُو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_31.mp3', '', 1761754199, 1761754199),
(49698, 'Jeremiah 7:32', 'Jeremiah', 7, 32, 'خو خبردار، يو وخت داسې راروان دے چې دې ځائ ته به نور د توفت يا د بنى‌هنوم وادى نۀ وائى بلکې خلق به ورته د قتل و غارت وادى وائى. ځکه چې هلته به دومره ډېر لاشونه ښخ کړے شى چې نور به د ښخولو دپاره ځائ نۀ وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_32.mp3', '', 1761754199, 1761754199),
(49699, 'Jeremiah 7:33', 'Jeremiah', 7, 33, 'نو د هغوئ لاشونه به د هوا مارغانو او د ځنګلى ځناورو خوراک شى او داسې څوک به ژوندى نۀ وى چې دا ترې نه وشړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_33.mp3', '', 1761754199, 1761754199),
(49700, 'Jeremiah 7:34', 'Jeremiah', 7, 34, 'زۀ به د يهوداه په ښارونو او د يروشلم په کوڅو کښې د خندا خوشحالۍ آوازونه ختم کړم. د ناوې او زلمى آوازونه به نور په دې ښارونو کښې نۀ اورېدلے کيږى. ځکه چې دا مُلک به وران ويجاړ وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/jeremiah7_verse_34.mp3', '', 1761754199, 1761754199),
(49701, 'Isaiah 11:1', 'Isaiah', 11, 1, 'د یسي د زوی داود شاهي کورنۍ د هغې ونې په شان ده چې وهل شوې وي، خو څنګه چې د هغې ونې له تنې څخه نوې څانګې راشنې کیږي نو همداسې به د داود د اولادې څخه «یوه څانګه» یعنې یو نوی پاچا راڅرګند شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_1.mp3', '', 1761754199, 1761754199),
(49702, 'Isaiah 11:2', 'Isaiah', 11, 2, 'د څښتن روح به له هغه سره وي هغه روح چې ورکوي خلکو ته پوهه او حکمت هغه روح چې ورکوي مشوره او قوت وي به د څښتن د پېژندنې او درناوي روح', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_2.mp3', '', 1761754199, 1761754199),
(49703, 'Isaiah 11:3', 'Isaiah', 11, 3, 'او خوشحالیږي به هغه د څښتن وېره کې په ظاهري بڼه د چا به قضاوت نه کوي او نه به کوي پرېکړه هسې خبرو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_3.mp3', '', 1761754199, 1761754199),
(49704, 'Isaiah 11:4', 'Isaiah', 11, 4, 'بلکې کوي به قضاوت د غریبانو د انصاف له مخې او کړي دفاع به د بې وزلو د حقونو څخه د هغه د کلام زور به ولړزوي ځمکه یو پوکی به یې د خولې یوسي له منځه بدکاران', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_4.mp3', '', 1761754199, 1761754199),
(49705, 'Isaiah 11:5', 'Isaiah', 11, 5, 'وي عدالت به د هغه ملاتړ وفاداري به یې وي کمربند', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_5.mp3', '', 1761754199, 1761754199),
(49706, 'Isaiah 11:6', 'Isaiah', 11, 6, 'د هغه په پاچاهۍ کې به لېوان او وري یوځای اوسي د سېرلو سره به یوځای وي پړانګان پراته خوسیان به د زمریانو د بچو سره یوځای خوراک کړي او دوی به پیایي یو وړوکی ماشوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_6.mp3', '', 1761754199, 1761754199),
(49707, 'Isaiah 11:7', 'Isaiah', 11, 7, 'خوراک به یوځای کوي اېږې او غواګانې سره او د هغوی بچیان به یوځای وي په امن پراته زمریان به خوري بوس د غویانو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_7.mp3', '', 1761754199, 1761754199),
(49708, 'Isaiah 11:8', 'Isaiah', 11, 8, 'کړي د شیدو ماشوم به لوبې د چمچه مار سوړه کې له شیدو څخه بېل شوی ماشوم وهي سوړه کې به لاس د زهرجن مار', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_8.mp3', '', 1761754199, 1761754199),
(49709, 'Isaiah 11:9', 'Isaiah', 11, 9, 'زما په سپېڅلي غره صهیون باندې به هېچا او هېڅ شي ته به ونه رسي زیان او نه به له منځه لاړ شي لکه چې څنګه دي بحرونه د اوبو څخه ډک نړۍ به دغه شان وي ډکه د څښتن د پېژندنې څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_9.mp3', '', 1761754199, 1761754199),
(49710, 'Isaiah 11:10', 'Isaiah', 11, 10, 'داسې ورځ به راشي چې د یسي د زوی داود د کورنۍ څخه به یو نوی پاچا د ټولو قومونو دپاره یو بیرغ وي. هغوی به د هغه په لټه کې وي او د هغه استوګنځی به له جلاله ډک وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah11_verse_10.mp3', '', 1761754199, 1761754199);